+ * MIPI DSI 引脚配置 (PD.18-PD.27, function=4)
+ * 来源: luban-lite target/d13x/demo88-nor/pinmux.c
+ ****************************************************************************/
+
+static void d13x_dsi_pinmux_init(void)
+{
+  uint32_t val;
+  uint32_t pin;
+
+  /* PD.18 - PD.27: MIPI DSI 数据/时钟引脚
+   * 功能号 = 4 (MIPI DSI 模式)
+   * 驱动强度 = 3
+   * 上拉/下拉 = 禁用
+   *
+   * GPIO PD 基地址 = GPIO_BASE + 3*0x100 = 0x18700300
+   * 引脚配置寄存器 = PD_BASE + pin*0x4 + 0x80
+   */
+
+  for (pin = 18; pin <= 27; pin++)
+    {
+      val = getreg32(D13X_GPIO_BASE + 3 * GPIO_GROUP_FACTOR +
+                     pin * GPIO_PIN_FACTOR + GPIO_PIN_CFG_REG);
+      val &= ~(GPIO_PIN_FUN_MASK << GPIO_PIN_FUN_SHIFT);
+      val |= (4 & GPIO_PIN_FUN_MASK) << GPIO_PIN_FUN_SHIFT;  /* function 4 = MIPI DSI */
+      putreg32(val, D13X_GPIO_BASE + 3 * GPIO_GROUP_FACTOR +
+               pin * GPIO_PIN_FACTOR + GPIO_PIN_CFG_REG);
+    }
+}
+
