+
+  val = getreg32(D13X_GPIO_BASE + 0 * GPIO_GROUP_FACTOR +
+                 0 * GPIO_PIN_FACTOR + GPIO_PIN_CFG_REG);
+  val &= ~(GPIO_PIN_FUN_MASK << GPIO_PIN_FUN_SHIFT);
+  val |= (UART0_PIN_FUN & GPIO_PIN_FUN_MASK) << GPIO_PIN_FUN_SHIFT;
+  putreg32(val, D13X_GPIO_BASE + 0 * GPIO_GROUP_FACTOR +
+           0 * GPIO_PIN_FACTOR + GPIO_PIN_CFG_REG);
+
+  /* PA.1 (UART0_RX): GPIO_BASE + 0*0x100 + 1*0x4 + 0x80 = 0x18700084 */
+
+  val = getreg32(D13X_GPIO_BASE + 0 * GPIO_GROUP_FACTOR +
+                 1 * GPIO_PIN_FACTOR + GPIO_PIN_CFG_REG);
+  val &= ~(GPIO_PIN_FUN_MASK << GPIO_PIN_FUN_SHIFT);
+  val |= (UART0_PIN_FUN & GPIO_PIN_FUN_MASK) << GPIO_PIN_FUN_SHIFT;
+  putreg32(val, D13X_GPIO_BASE + 0 * GPIO_GROUP_FACTOR +
