#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/gpio.h>
#include <debug.h>
#include "chip.h"
#include "artinchip_dsi.h"

/* 位操作宏 */

#ifndef BIT
#define BIT(nr)         (1UL << (nr))
#endif

/* 背光控制 GPIO 配置
 * 请根据实际硬件原理图修改以下配置
 * 格式: GPIO_GROUP(group) + GPIO_PIN(pin)
 * 示例: PE.0 = group 4, pin 0
 */

#define BACKLIGHT_GPIO_GROUP      4  /* PE 组 = 4 */
#define BACKLIGHT_GPIO_PIN        0  /* PE.0 */
#define BACKLIGHT_ACTIVE_HIGH     1  /* 1=高电平有效, 0=低电平有效 */

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: d13x_backlight_init
 *
 * Description:
 *   初始化背光 GPIO
 *
 ****************************************************************************/

static void d13x_backlight_init(void)
{
  uint32_t val;
  uint32_t gpio_base = D13X_GPIO_BASE + BACKLIGHT_GPIO_GROUP * 0x100;

  /* 配置为 GPIO 功能 (function 1) */

  val = getreg32(gpio_base + BACKLIGHT_GPIO_PIN * 0x4 + 0x80);
  val &= ~(0xF << 0);
  val |= (1 << 0);  /* function 1 = GPIO */
  putreg32(val, gpio_base + BACKLIGHT_GPIO_PIN * 0x4 + 0x80);

  /* 配置为输出模式 */

  val = getreg32(gpio_base + 0x40);  /* GPIO_DIR 寄存器 */
  val |= (1 << BACKLIGHT_GPIO_PIN);
  putreg32(val, gpio_base + 0x40);

  iinfo("Backlight GPIO P%c.%d initialized\n",
        'A' + BACKLIGHT_GPIO_GROUP, BACKLIGHT_GPIO_PIN);
}

/****************************************************************************
 * Name: d13x_backlight_enable
 *
 * Description:
 *   使能背光
 *
 ****************************************************************************/

static void d13x_backlight_enable(void)
{
  uint32_t gpio_base = D13X_GPIO_BASE + BACKLIGHT_GPIO_GROUP * 0x100;

  if (BACKLIGHT_ACTIVE_HIGH)
    {
      putreg32((1 << BACKLIGHT_GPIO_PIN), gpio_base + 0x30);  /* GPIO_SET */
    }
  else
    {
      putreg32((1 << BACKLIGHT_GPIO_PIN), gpio_base + 0x34);  /* GPIO_CLR */
    }

  iinfo("Backlight enabled\n");
}

/****************************************************************************
 * Name: d13x_backlight_disable
 *
 * Description:
 *   禁用背光
 *
 ****************************************************************************/

static void d13x_backlight_disable(void)
{
  uint32_t gpio_base = D13X_GPIO_BASE + BACKLIGHT_GPIO_GROUP * 0x100;

  if (BACKLIGHT_ACTIVE_HIGH)
    {
      putreg32((1 << BACKLIGHT_GPIO_PIN), gpio_base + 0x34);  /* GPIO_CLR */
    }
  else
    {
      putreg32((1 << BACKLIGHT_GPIO_PIN), gpio_base + 0x30);  /* GPIO_SET */
    }

  iinfo("Backlight disabled\n");
}

