metadata.diff:
Index: /home/lladlam/OpenVela/openvela/vendor/artinchip/boards/d13x-hengshan-pi/src/artinchip_touch.c
===================================================================
--- /home/lladlam/OpenVela/openvela/vendor/artinchip/boards/d13x-hengshan-pi/src/artinchip_touch.c
+++ /home/lladlam/OpenVela/openvela/vendor/artinchip/boards/d13x-hengshan-pi/src/artinchip_touch.c
@@ -206,9 +206,9 @@
 {
   uint32_t group = GPIO_GROUP(GT911_INT_PIN);
   uint32_t pin = GPIO_PIN(GT911_INT_PIN);

-  /* 清除 PA2 GPIO 中断状态 (写1清除) */
+  /* 清除 PA9 GPIO 中断状态 (写1清除) */

   putreg32((1 << pin), D13X_GPIO_IRQ_STAT(group));

   /* 调用原始 gt9xx ISR */
@@ -234,16 +234,16 @@

   g_gt911_isr = isr;
   g_gt911_arg = arg;

-  /* 配置 PA2 为 GPIO 通用功能 (PIN_FUN=1) */
+  /* 配置 PA9 为 GPIO 通用功能 (PIN_FUN=1) */

   val = getreg32(D13X_GPIO_PIN_CFG(group, pin));
   val &= ~(PIN_CFG_FUN_MASK << PIN_CFG_FUN_SHIFT);
   val |= (GPIO_FUN_GEN << PIN_CFG_FUN_SHIFT);
   putreg32(val, D13X_GPIO_PIN_CFG(group, pin));

-  /* 配置 PA2 为输入 */
+  /* 配置 PA9 为输入 */

   gpio_set_input(GT911_INT_PIN);

   /* 配置中断模式: 下降沿触发 (GT911 中断低电平有效) */
@@ -277,9 +277,9 @@
       /* 清除中断状态 */

       putreg32((1 << pin), D13X_GPIO_IRQ_STAT(group));

-      /* 使能 PA2 中断 */
+      /* 使能 PA9 中断 */

       val = getreg32(D13X_GPIO_TRQ_EN(group));
       val |= (1 << pin);
       putreg32(val, D13X_GPIO_TRQ_EN(group));
@@ -289,9 +289,9 @@
       up_enable_irq(D13X_IRQ_GPIO);
     }
   else
     {
-      /* 禁用 PA2 中断 */
+      /* 禁用 PA9 中断 */

       val = getreg32(D13X_GPIO_TRQ_EN(group));
       val &= ~(1 << pin);
       putreg32(val, D13X_GPIO_TRQ_EN(group));

