static void d13x_uart_rxint(FAR struct uart_dev_s *dev, bool enable)
{
  /* 使能/禁用接收中断 */

  uint32_t ier = getreg32(D13X_UART0_BASE + UART_DLH_IER);

  if (enable)
    {
      ier |= 0x01;
    }
  else
    {
      ier &= ~0x01;
    }

  putreg32(ier, D13X_UART0_BASE + UART_DLH_IER);
}

