void artinchip_bringup(void)
{
  int ret;

#ifdef CONFIG_D13X_I2C
  ret = d13x_i2c_bus_initialize();
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: I2C init failed: %d\n", ret);
    }
#endif

#ifdef CONFIG_D13X_TOUCH_GT911
  ret = d13x_touch_initialize();
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Touch init failed: %d\n", ret);
    }
#endif

#ifdef CONFIG_VIDEO_FB
  /* 初始化帧缓冲 */

  ret = up_fbinitialize(0);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: FB init failed: %d\n", ret);
    }
  else
    {
      ret = fb_register(0, 0);
      if (ret < 0)
        {
          syslog(LOG_ERR, "ERROR: FB register failed: %d\n", ret);
        }
    }
#endif
}

