static void d13x_uart_init(void)
{
  uint32_t divisor;

  /* 允许在 UART 忙碌时配置 (来源: D13x官方文档 + luban-lite aic_hal_uart.c) */

  putreg32(UART_HALT_CHCFG_AT_BUSY, D13X_UART0_BASE + UART_HALT);

  /* 禁用中断 */

  putreg32(0, D13X_UART0_BASE + UART_DLH_IER);

  /* 设置 DLAB=1 以访问 DLL/DLH */

  putreg32(UART_LCR_DLAB, D13X_UART0_BASE + UART_LCR);

  /* 使用四舍五入计算分频系数 (来源: luban-lite aic_hal_uart.c) */

  divisor = (D13X_UART0_FREQ + 16 * D13X_UART0_BAUDRATE / 2) /
            (16 * D13X_UART0_BAUDRATE);

  /* 写入波特率除数 */

  putreg32(divisor & 0xFF, D13X_UART0_BASE + UART_RBR_THR_DLL);
  putreg32((divisor >> 8) & 0xFF, D13X_UART0_BASE + UART_DLH_IER);

  /* 清除 DLAB 以访问其他寄存器 (来源: luban-lite aic_hal_uart.c) */

  putreg32(0x03, D13X_UART0_BASE + UART_LCR);

  /* 应用配置变更 (来源: D13x官方文档 - CHANGE_UPDATE 写1更新，完成后自动清0) */

  putreg32(UART_HALT_CHANGE_UPDATE, D13X_UART0_BASE + UART_HALT);

  /* 使能 FIFO */

  putreg32(UART_FCR_FIFOE | UART_FCR_RFIFOR | UART_FCR_XFIFOR,
           D13X_UART0_BASE + UART_FCR_IIR);
}

