static void d13x_uart_init(void)
{
  uint32_t divisor;

  /* 允许在 UART 忙碌时配置 (来源: D13x官方文档 + luban-lite aic_hal_uart.c) */

  putreg32(UART_HALT_CHCFG_AT_BUSY, D13X_UART0_BASE + UART_HALT);

  /* 禁用中断 */

  putreg32(0, D13X_UART0_BASE + UART_DLH_IER);

  /* 设置 DLAB=1 以访问 DLL/DLH */

  putreg32(UART_LCR_DLAB, D13X_UART0_BASE + UART_LCR);

  /* 使用四舍五入计算分频系数 (来源: luban-lite aic_hal_uart.c) */

  divisor = (D13X_UART0_FREQ + 16 * D13X_UART0_BAUDRATE / 2) /
            (16 * D13X_UART0_BAUDRATE);

reg = getreg32(CMU_CLK_GPIO);
reg |= (1 << 13) | (1 << 12) | (1 << 8);
putreg32(reg, CMU_CLK_GPIO);

/* 9. UART0 = 48MHz (PLL_INT1/(24+1)), 含 MOD_BUS_EN */

putreg32(UART_CLK_MOD_RSTN | UART_CLK_MOD_BUS_EN | UART_CLK_MOD_CLK_EN | 24,
         CMU_CLK_UART0);

/* 10. 显示时钟使能 (来源: luban-lite aic_board_sysclk_init)
 *     - MIPI DSI: CMU_CLK_MIPIDSI (0x0888)
 *     - Display Engine: CMU_CLK_DE (0x08C0)
 *     - RGB/TCON: CMU_CLK_RGB (0x0880)
 *     位域: MOD_RSTN(bit13) + MOD_BUS_EN(bit12) + MOD_CLK_EN(bit8)
 */

reg = getreg32(CMU_CLK_MIPIDSI);
reg |= DISP_CLK_MOD_RSTN | DISP_CLK_MOD_BUS_EN | DISP_CLK_MOD_CLK_EN;
putreg32(reg, CMU_CLK_MIPIDSI);

