#include <stdint.h>
#include <string.h>
#include "d13x_boot.h"

/****************************************************************************
 * 常量定义 (D13x 正确地址)
 ****************************************************************************/

#define OS_LOAD_ADDR    0x40000000  /* PSRAM 起始地址 (NuttX 加载到 PSRAM) */
#define FLASH_BASE      0x60000000  /* SPI NOR Flash XIP 映射地址 */
#define SRAM_BASE       0x30040000  /* D13x SRAM 基地址 */
#define PSRAM_BASE      0x40000000  /* D13x PSRAM 基地址 */
#define FLASH_SIZE      (16 * 1024 * 1024)  /* 16MB Flash */
#define SECTOR_SIZE     4096        /* 4KB 扇区大小 */

/* USB 协议命令 */

#define CMD_WRITE       0x01
#define CMD_READ        0x02
#define CMD_ERASE       0x03
#define CMD_INFO        0x04
#define CMD_BOOT        0x05
#define CMD_ACK         0x06
#define CMD_NAK         0x07

/****************************************************************************
 * 外部符号
 ****************************************************************************/

extern void d13x_clock_init(void);
extern void d13x_uart_init(void);
extern void d13x_putc(char ch);
extern int d13x_getc(void);
--
int main(void)
{
  /* 初始化硬件 */

  d13x_clock_init();
  d13x_uart_init();
  d13x_flash_init();
  d13x_psram_init();

  /* 输出启动信息 */

  print_str("\r\nD13x tinySPL v2.1\r\n");
  print_str("Flash ID: ");
  print_hex(d13x_flash_read_id());
  print_str("\r\n");
  print_str("PSRAM mark_id: 0x");
  print_hex(d13x_psram_get_mark_id());
  print_str("\r\n");
  print_str("PSRAM size: ");
  print_hex(d13x_psram_get_size());
  print_str(" bytes\r\n");

  /* 主循环：等待命令 */

  while (1)
  {
    if (!d13x_uart_rxready())
      continue;

    uint8_t cmd = d13x_getc();

