        if (addr + len > FLASH_SIZE)
        {
          send_nak();
          break;
        }

        /* 擦除需要的扇区 (只擦除一次) */
        uint32_t sector_start = addr & ~(SECTOR_SIZE - 1);
        uint32_t sector_end = (addr + len + SECTOR_SIZE - 1) & ~(SECTOR_SIZE - 1);
        uint32_t sector_addr;
        for (sector_addr = sector_start; sector_addr < sector_end; sector_addr += SECTOR_SIZE)
        {
          d13x_flash_erase_sector(sector_addr);
        }

        /* 连续写入数据 */
        while (remaining > 0)
        {
          uint32_t chunk = remaining > 256 ? 256 : remaining;
          uint32_t i;
          for (i = 0; i < chunk; i++)
            buf[i] = d13x_getc();

          d13x_flash_write(addr + offset, buf, chunk);

          offset += chunk;
          remaining -= chunk;
        }

        send_ack();
        break;
      }

      case CMD_READ:
      {
        uint32_t addr = recv_u32();
        uint32_t len = recv_u32();
        uint32_t i;

        /* 安全检查：只允许读取 Flash 区域 */
        if (addr + len > FLASH_SIZE)
        {
          send_nak();
          break;
        }

        /* 通过 SPI Flash 读取数据 */
        extern uint8_t d13x_flash_read(uint32_t addr, uint8_t *data, int len);
        uint8_t read_buf[256];
        uint32_t remaining = len;
        uint32_t offset = 0;

        while (remaining > 0)
        {
          uint32_t chunk = remaining > 256 ? 256 : remaining;
          d13x_flash_read(addr + offset, read_buf, chunk);
          for (i = 0; i < chunk; i++)
            d13x_putc(read_buf[i]);
          offset += chunk;
          remaining -= chunk;
        }

        send_ack();
        break;
      }

      case CMD_INFO:
      {
        send_u32(SRAM_BASE);   /* SRAM base */
        send_u32(PSRAM_BASE);  /* PSRAM base */
        send_u32(FLASH_BASE);  /* Flash base */
        send_u32(FLASH_SIZE);  /* Flash size */
        send_ack();
        break;
      }

      case CMD_BOOT:
      {
        print_str("Booting...\r\n");
        send_ack();

        /* 跳转到 OS 入口 */
        void (*entry)(void) = (void (*)(void))OS_LOAD_ADDR;
        entry();
        break;
      }

