void boot_app(void *app)
{
    int ret;
    void (*ep)(int);
    enum boot_device dev;

    ret = console_get_ctrlc();
    if (ret > 0)
        return;
#ifndef LPKG_USING_FDTLIB
    ep = image_get_entry_point(app);
    if (!ep) {
        printf("Entry point is null.\n");
        while(1)
            continue;
    }
