/****************************************************************************
 * D13x tinySPL Bootloader - system.c
 *
 * 完整的系统初始化：时钟、UART、SPI Flash、PSRAM
 * 地址来源: luban-lite aic_soc.h + D13x User Manual
 *
 ****************************************************************************/

#include <stdint.h>
#include "d13x_boot.h"

/****************************************************************************
 * CSR 寄存器访问 (来源: luban-lite core_rv32.h)
 ****************************************************************************/

/* T-Head E907 扩展 CSR */

#define CSR_MXSTATUS     0x7C0
#define CSR_MEXSTATUS    0x7C1
#define CSR_MSTATUS      0x300
#define CSR_MTVEC        0x305
#define CSR_MTVT         0x7C5   /* T-Head E907 mtvt CSR, 非 0x7C0 */

/****************************************************************************
 * SystemInit (来源: luban-lite system.c)
 * 由 startup.S 在 BSS 清零后调用
 ****************************************************************************/

void SystemInit(void)
{
  /* 使能 mstatus FS (FPU) */

  uint32_t mstatus;
  __asm__ __volatile__("csrr %0, mstatus" : "=r"(mstatus));
  mstatus |= (1 << 13);  /* FS = 01 (Initial) */
  __asm__ __volatile__("csrw mstatus, %0" :: "r"(mstatus));

  /* 使能 mxstatus THEADISAEE (T-Head ISA 扩展) */

  uint32_t mxstatus;
  __asm__ __volatile__("csrr %0, 0x7C0" : "=r"(mxstatus));
  mxstatus |= (1 << 22);  /* THEADISAEE */
  mxstatus |= (1 << 15);  /* MM (Memory Management) */
  __asm__ __volatile__("csrw 0x7C0, %0" :: "r"(mxstatus));

  /* 使能 mexstatus SPUSHEN/SPSWAPEN */

  uint32_t mexstatus;
  __asm__ __volatile__("csrr %0, 0x7C1" : "=r"(mexstatus));
  mexstatus |= (1 << 16);  /* SPUSHEN */
  mexstatus |= (1 << 17);  /* SPSWAPEN */
  __asm__ __volatile__("csrw 0x7C1, %0" :: "r"(mexstatus));
}

/****************************************************************************
 * 寄存器访问宏
 ****************************************************************************/

#define getreg32(a)     (*(volatile uint32_t *)(a))
#define putreg32(v,a)   (*(volatile uint32_t *)(a) = (v))

/****************************************************************************
 * 外设基地址 (来源: luban-lite aic_soc.h)
 ****************************************************************************/

#define CMU_BASE        0x18020000
#define GPIO_BASE       0x18700000
#define UART0_BASE      0x18710000
#define XSPI_BASE       0x10300000  /* XSPI PSRAM 控制器 */
#define QSPI0_BASE      0x10400000  /* QSPI0 SPI Flash */
#define WDT_BASE        0x19000000  /* Watchdog */
#define SID_BASE        0x19010000  /* eFuse */

/****************************************************************************
 * PSRAM 配置 (D13x)
 ****************************************************************************/

#define PSRAM_BASE          0x40000000
#define PSRAM_SIZE          (8 * 1024 * 1024)  /* 8MB */

/* eFuse 寄存器 */

#define EFUSE_CMU_REG       (CMU_BASE + 0x904)
#define EFUSE_218_REG       (SID_BASE + 0x218)
#define EFUSE_224_REG       (SID_BASE + 0x224)

/* PSRAM 芯片 ID */

#define PSRAM_CHIP_APS3208K 0x80c9
#define PSRAM_CHIP_SCKW18   0xc59a
#define PSRAM_CHIP_APS12816 0xdd8d

/****************************************************************************
 * 时钟系统 (CMU)
 ****************************************************************************/

void d13x_clock_init(void)
{
  uint32_t reg;

  /* 打开 24MHz 振荡器 (PLL_IN bit1) */

  reg = getreg32(CMU_BASE + 0x0A4);
  reg |= (1 << 1);
  putreg32(reg, CMU_BASE + 0x0A4);

  /* PLL 公共电路 LDO (PLL_COM bit31 + bit0) */

  reg = getreg32(CMU_BASE + 0x0A0);
  reg |= (1 << 31) | (1 << 0);
  putreg32(reg, CMU_BASE + 0x0A0);

  /* 使能 PLL_INT1 → 1.2GHz (PLL_INT1_GEN bit0=ENABLE, bit17=LOCK)
   * 默认 FACTOR_N=0x31(49), 24*(49+1)=1200MHz
   */

  reg = getreg32(CMU_BASE + 0x004);  /* PLL_INT1_GEN */
  reg |= (1 << 16);  /* PLL_EN bit16 (非 bit0) */
  putreg32(reg, CMU_BASE + 0x004);
  while (!(getreg32(CMU_BASE + 0x004) & (1 << 17)));

  /* 使能 PLL_INT0 → 480MHz (设置 FACTOR_N=19, 24*(19+1)=480MHz) */

  reg = getreg32(CMU_BASE + 0x000);  /* PLL_INT0_GEN */
  reg &= ~(0xFF << 8);  /* 清除 FACTOR_N */
  reg |= (19 << 8);     /* N=19 → 480MHz */
  reg |= (1 << 16);     /* PLL_EN bit16 (非 bit0) */
  putreg32(reg, CMU_BASE + 0x000);
  while (!(getreg32(CMU_BASE + 0x000) & (1 << 17)));

  /* AXI/AHB = 200MHz (PLL_INT1 源, div=5 → 1200/6=200MHz) */

  putreg32((1 << 8) | 5, CMU_BASE + 0x100);

  /* APB0 = 100MHz (PLL_INT1 源, div=11 → 1200/12=100MHz) */

  putreg32((1 << 8) | 11, CMU_BASE + 0x120);

  /* CPU = 480MHz (PLL_INT0 源, div=0 → 480MHz) */

  putreg32((1 << 8) | 0, CMU_BASE + 0x200);

  /* GPIO 时钟 */

  reg = getreg32(CMU_BASE + 0x83C);
  reg |= (1 << 12) | (1 << 13);
  putreg32(reg, CMU_BASE + 0x83C);

  /* UART0 = 60MHz (PLL_INT1 源, div=19, 含 MOD_BUS_EN) */

  putreg32((1 << 13) | (1 << 12) | (1 << 8) | 19, CMU_BASE + 0x840);

  /* QSPI0 时钟: 释放复位 + 使能总线时钟 + 使能模块时钟 (CMU_BASE + 0x460) */

  putreg32((1 << 13) | (1 << 12) | (1 << 8), CMU_BASE + 0x460);

  /* XSPI 时钟: 释放复位 + 使能总线时钟 + 使能模块时钟 (CMU_BASE + 0x45C) */

  putreg32((1 << 13) | (1 << 12) | (1 << 8), CMU_BASE + 0x45C);
}

/****************************************************************************
 * UART 驱动 (UART0 基地址: 0x18710000)
 ****************************************************************************/

void d13x_uart_init(void)
{
  uint32_t divisor = 60000000 / (16 * 115200);

  /* 等待 UART 空闲 (USR bit0=0) */

  while (getreg32(UART0_BASE + 0x7C) & (1 << 0));

  /* 禁用中断 */

  putreg32(0, UART0_BASE + 0x04);

  /* 设置 DLAB=1 以访问 DLL/DLH */

  putreg32(0x80, UART0_BASE + 0x0C);        /* LCR bit7=1 (DLAB) */

  /* 写入波特率除数 */

  putreg32(divisor & 0xFF, UART0_BASE + 0x00);       /* DLL */
  putreg32((divisor >> 8) & 0xFF, UART0_BASE + 0x04); /* DLH */

  /* 使能 FIFO, 清除 DLAB, 设置 8N1 */

  putreg32(0x07, UART0_BASE + 0x08);        /* FIFO: enable + reset */
  putreg32(0x03, UART0_BASE + 0x0C);        /* LCR: 8N1, DLAB=0 */
}

void d13x_putc(char ch)
{
  while (!(getreg32(UART0_BASE + 0x14) & (1 << 5)));  /* LSR.THRE */
  putreg32((uint32_t)ch, UART0_BASE + 0x00);
}

int d13x_getc(void)
{
  while (!(getreg32(UART0_BASE + 0x14) & (1 << 0)));  /* LSR.DR */
  return (int)(getreg32(UART0_BASE + 0x00) & 0xFF);
}

int d13x_uart_rxready(void)
{
  return (getreg32(UART0_BASE + 0x14) & (1 << 0)) != 0;
}

/****************************************************************************
 * QSPI 控制器 (D13x)
 * QSPI0 基地址: 0x10400000 (来源: luban-lite aic_soc.h)
 ****************************************************************************/

#define QSPI_BASE      QSPI0_BASE
#define QSPI_VER       (QSPI_BASE + 0x000)
#define QSPI_CFG       (QSPI_BASE + 0x004)
#define QSPI_TCFG      (QSPI_BASE + 0x008)
#define QSPI_ICR       (QSPI_BASE + 0x010)
#define QSPI_ISTS      (QSPI_BASE + 0x014)
#define QSPI_FCTL      (QSPI_BASE + 0x018)
#define QSPI_FSTS      (QSPI_BASE + 0x01C)
#define QSPI_CCFG      (QSPI_BASE + 0x024)
#define QSPI_TXD       (QSPI_BASE + 0x200)
#define QSPI_RXD       (QSPI_BASE + 0x300)

/* QSPI_CFG bits */

#define QSPI_CFG_EN        (1 << 0)
#define QSPI_CFG_MASTER    (1 << 1)
#define QSPI_CFG_RST       (1 << 31)

/* QSPI_TCFG bits */

#define QSPI_TCFG_CPHA     (1 << 0)
#define QSPI_TCFG_CPOL     (1 << 1)
#define QSPI_TCFG_CS_LOW   (0 << 7)
#define QSPI_TCFG_CS_HIGH  (1 << 7)
#define QSPI_TCFG_CS_SW    (1 << 6)
#define QSPI_TCFG_START    (1 << 31)

/* QSPI_FSTS bits */

#define QSPI_FSTS_TD       (1 << 12)
#define QSPI_FSTS_TF_EMP   (1 << 5)
#define QSPI_FSTS_RF_RDY   (1 << 0)

static void d13x_spi_init(void)
{
  /* 复位控制器 */

  putreg32(QSPI_CFG_RST, QSPI_CFG);
  while (getreg32(QSPI_CFG) & QSPI_CFG_RST);

  /* 使能控制器 + 主机模式 */

  putreg32(QSPI_CFG_EN | QSPI_CFG_MASTER, QSPI_CFG);

  /* 时钟分频: SPI_CLK = src_clk / (2 * (CKDIV2 + 1))
   * src=480MHz, CKDIV2=15 → SPI_CLK = 480/(2*16) = 15MHz */

  putreg32(15, QSPI_CCFG);

  /* 传输配置: Mode 0 (CPOL=0, CPHA=0), 软件控制CS */

  putreg32(QSPI_TCFG_CS_SW | QSPI_TCFG_CS_HIGH, QSPI_TCFG);

  /* 复位 FIFO */

  putreg32((1 << 31) | (1 << 15), QSPI_FCTL);
}

static void d13x_spi_cs(int assert)
{
  uint32_t reg = getreg32(QSPI_TCFG);
  if (assert)
    reg &= ~QSPI_TCFG_CS_HIGH;
  else
    reg |= QSPI_TCFG_CS_HIGH;
  putreg32(reg, QSPI_TCFG);
}

static void d13x_spi_txrx(uint8_t *tx, uint8_t *rx, int len)
{
  int i;
  for (i = 0; i < len; i++)
    {
      /* 写入 TX FIFO */

      putreg32(tx ? tx[i] : 0, QSPI_TXD);

      /* 启动传输 */

      uint32_t tcfg = getreg32(QSPI_TCFG);
      putreg32(tcfg | QSPI_TCFG_START, QSPI_TCFG);

      /* 等待传输完成 */

      while (!(getreg32(QSPI_FSTS) & QSPI_FSTS_TD));

      /* 清除 TD 标志 (W1C) */

      putreg32(QSPI_FSTS_TD, QSPI_ISTS);

      /* 读取 RX FIFO */

      if (rx)
        rx[i] = (uint8_t)getreg32(QSPI_RXD);
    }
}

/****************************************************************************
 * SPI NOR Flash 驱动
 ****************************************************************************/

#define FLASH_WRITE_ENABLE    0x06
#define FLASH_READ_STATUS     0x05
#define FLASH_READ_DATA       0x03
#define FLASH_PAGE_PROGRAM    0x02
#define FLASH_SECTOR_ERASE    0x20
#define FLASH_READ_ID         0x9F

static void d13x_flash_write_enable(void)
{
  uint8_t cmd = FLASH_WRITE_ENABLE;
  d13x_spi_cs(1);
  d13x_spi_txrx(&cmd, 0, 1);
  d13x_spi_cs(0);
}

static void d13x_flash_wait_busy(void)
{
  uint8_t cmd = FLASH_READ_STATUS;
  uint8_t status;
  do {
    d13x_spi_cs(1);
    d13x_spi_txrx(&cmd, 0, 1);
    d13x_spi_txrx(0, &status, 1);
    d13x_spi_cs(0);
  } while (status & 0x01);
}

void d13x_flash_write(uint32_t addr, uint8_t *data, int len)
{
  uint8_t cmd[4];
  cmd[0] = FLASH_PAGE_PROGRAM;
  cmd[1] = (addr >> 16) & 0xFF;
  cmd[2] = (addr >> 8) & 0xFF;
  cmd[3] = addr & 0xFF;

  d13x_flash_write_enable();
  d13x_spi_cs(1);
  d13x_spi_txrx(cmd, 0, 4);
  d13x_spi_txrx(data, 0, len);
  d13x_spi_cs(0);
  d13x_flash_wait_busy();
}

void d13x_flash_erase_sector(uint32_t addr)
{
  uint8_t cmd[4];
  cmd[0] = FLASH_SECTOR_ERASE;
  cmd[1] = (addr >> 16) & 0xFF;
  cmd[2] = (addr >> 8) & 0xFF;
  cmd[3] = addr & 0xFF;

  d13x_flash_write_enable();
  d13x_spi_cs(1);
  d13x_spi_txrx(cmd, 0, 4);
  d13x_spi_cs(0);
  d13x_flash_wait_busy();
}

uint32_t d13x_flash_read_id(void)
{
  uint8_t cmd = FLASH_READ_ID;
  uint8_t id[3];
  uint32_t result;

  d13x_spi_cs(1);
  d13x_spi_txrx(&cmd, 0, 1);
  d13x_spi_txrx(0, id, 3);
  d13x_spi_cs(0);

  result = (id[0] << 16) | (id[1] << 8) | id[2];
  return result;
}

uint8_t d13x_flash_read(uint32_t addr, uint8_t *data, int len)
{
  uint8_t cmd[4];
  cmd[0] = FLASH_READ_DATA;
  cmd[1] = (addr >> 16) & 0xFF;
  cmd[2] = (addr >> 8) & 0xFF;
  cmd[3] = addr & 0xFF;

  d13x_spi_cs(1);
  d13x_spi_txrx(cmd, 0, 4);
  d13x_spi_txrx(0, data, len);
  d13x_spi_cs(0);

  return 0;
}

void d13x_flash_init(void)
{
  d13x_spi_init();
}

/****************************************************************************
 * PSRAM 驱动 (D13x)
 * XSPI 基地址: 0x10300000 (来源: luban-lite aic_soc.h)
 * 寄存器映射: luban-lite xspi_hw_v1.0.h
 ****************************************************************************/

/* XSPI 控制器寄存器 (来源: luban-lite xspi_hw_v1.0.h) */

#define XSPI_CTL            (XSPI_BASE + 0x000)
#define XSPI_CLK_REG        (XSPI_BASE + 0x004)
#define XSPI_TCR            (XSPI_BASE + 0x008)
#define XSPI_STAS           (XSPI_BASE + 0x00C)
#define XSPI_FCR            (XSPI_BASE + 0x028)
#define XSPI_START          (XSPI_BASE + 0x030)
#define XSPI_ADDR_REG       (XSPI_BASE + 0x034)
#define XSPI_LCKCR          (XSPI_BASE + 0x054)
#define XSPI_LUT_UP         (XSPI_BASE + 0x058)
#define XSPI_CS0_DCTL       (XSPI_BASE + 0x014)
#define XSPI_CS1_DCTL       (XSPI_BASE + 0x01C)
#define XSPI_CS0_IOCFG1     (XSPI_BASE + 0x070)
#define XSPI_CS0_IOCFG2     (XSPI_BASE + 0x074)
#define XSPI_CS0_IOCFG3     (XSPI_BASE + 0x078)
#define XSPI_CS0_IOCFG4     (XSPI_BASE + 0x07C)
#define XSPI_CS1_IOCFG1     (XSPI_BASE + 0x080)
#define XSPI_CS1_IOCFG2     (XSPI_BASE + 0x084)
#define XSPI_CS1_IOCFG3     (XSPI_BASE + 0x088)
#define XSPI_CS1_IOCFG4     (XSPI_BASE + 0x08C)
#define XSPI_TDR            (XSPI_BASE + 0x200)
#define XSPI_RDR            (XSPI_BASE + 0x300)
#define XSPI_LUTN(n)        (XSPI_BASE + 0x100 + 0x4 * (n))

/* XSPI_CTL 位域 */

#define CTL_XSPI_EN         (1 << 0)
#define CTL_XIP_EN          (1 << 2)
#define CTL_AXI_BURST       (1 << 3)
#define CTL_XSPI_MODE_SHIFT 4
#define CTL_BOUNDARY_EN     (1 << 12)
#define CTL_BOUNDARY_CTL    (1 << 13)

/* XSPI 模式 */

#define XSPI_MODE_OPI       2

/* XSPI_STAS 位域 */

#define STAS_BUSY            (1 << 0)

/* LUT 指令 */

#define LUT_STOP             0x0
#define LUT_CMD              0x1
#define LUT_ADDR             0x3
#define LUT_WRITE            0x4
#define LUT_READ             0x5

/* LUT IO 模式 */

#define LUT_IO_1             0x0
#define LUT_IO_8             0x3

/* LUT 锁定 */

#define LUT_LOCK             0x1
#define LUT_UNLOCK           0x2

/* LUT 条目编码 */

#define LUT_ENTRY(ins_h, io_h, op_h, ins_l, io_l, op_l) \
  (((ins_h) << 26) | ((io_h) << 24) | ((op_h) << 16) | \
   ((ins_l) << 10) | ((io_l) << 8) | (op_l))

/* PSRAM 命令 */

#define PSRAM_CMD_RESET     0xFF
#define PSRAM_CMD_READ_ID   0x40
#define PSRAM_CMD_WRITE_MR  0xC0
#define PSRAM_CMD_READ_MR   0x40
#define PSRAM_CMD_WRITE     0x80
#define PSRAM_CMD_READ      0x00

/* PSRAM 模式寄存器 */

#define PSRAM_MR0           0x00
#define PSRAM_MR1           0x01
#define PSRAM_MR2           0x02
#define PSRAM_MR4           0x04

static uint32_t d13x_psram_read_efuse(uint32_t reg_addr)
{
  /* 使能 eFuse 时钟 */

  putreg32(0x1100, EFUSE_CMU_REG);

  /* 读取 eFuse 值 */

  uint32_t val = getreg32(reg_addr);

  /* 关闭 eFuse 时钟 */

  putreg32(0x0, EFUSE_CMU_REG);

  return val;
}

uint8_t d13x_psram_get_mark_id(void)
{
  uint32_t fuse_218 = d13x_psram_read_efuse(EFUSE_218_REG);
  return fuse_218 & 0xFF;
}

uint8_t d13x_psram_get_psram_id(void)
{
  uint32_t fuse_224 = d13x_psram_read_efuse(EFUSE_224_REG);
  return (fuse_224 >> 20) & 0xFF;
}

uint32_t d13x_psram_get_size(void)
{
  uint8_t mark_id = d13x_psram_get_mark_id();

  /* 根据 mark_id 确定 PSRAM 大小 */

  switch (mark_id)
    {
      case 0x00:  /* force use cfg0 */
        return 0;
      case 0x01:  /* D131BAS 4M */
        return 4 * 1024 * 1024;
      case 0x02:  /* D131BBS 8M */
      case 0x03:  /* D131CBS 8M */
      case 0x04:  /* D131EBS/D133EBS 8M */
      case 0x05:  /* D132ENS 8M */
      case 0xA1:  /* DR128 8M */
      case 0xA2:  /* JYX68 8M */
        return 8 * 1024 * 1024;
      case 0x06:  /* D131CCS 16M */
      case 0x07:  /* D133ECS 16M */
        return 16 * 1024 * 1024;
      default:
        return 8 * 1024 * 1024;  /* 默认 8MB */
    }
}

static inline void xspi_wait_idle(void)
{
  while (getreg32(XSPI_STAS) & STAS_BUSY);
}

static void d13x_xspi_lut_write(int lut_id,
                                 int ins_l, int io_l, int op_l,
                                 int ins_h, int io_h, int op_h)
{
  uint32_t entry = LUT_ENTRY(ins_h, io_h, op_h, ins_l, io_l, op_l);
  putreg32(entry, XSPI_LUTN(lut_id));
}

static void d13x_xspi_lut_update(void)
{
  putreg32(1, XSPI_LUT_UP);
}

static void d13x_xspi_lut_lock(int lock)
{
  putreg32(lock ? LUT_LOCK : LUT_UNLOCK, XSPI_LCKCR);
}

static void d13x_xspi_trigger(int lut_id)
{
  xspi_wait_idle();
  putreg32(lut_id, XSPI_START);
  xspi_wait_idle();
}

static void d13x_psram_write_mr(uint8_t mr_addr, uint8_t mr_val)
{
  d13x_xspi_lut_write(0, LUT_CMD, LUT_IO_1, 0xC0, LUT_STOP, 0, 0);
  d13x_xspi_lut_write(1, LUT_ADDR, LUT_IO_1, 1, LUT_STOP, 0, 0);
  d13x_xspi_lut_write(2, LUT_WRITE, LUT_IO_1, 1, LUT_STOP, 0, 0);
  d13x_xspi_lut_update();
  putreg32(mr_addr, XSPI_ADDR_REG);
  putreg32((uint32_t)mr_val, XSPI_TDR);
  d13x_xspi_trigger(0);
}

static void d13x_psram_read_mr(uint8_t mr_addr, uint8_t *mr_val)
{
  d13x_xspi_lut_write(0, LUT_CMD, LUT_IO_1, 0x40, LUT_STOP, 0, 0);
  d13x_xspi_lut_write(1, LUT_ADDR, LUT_IO_1, 1, LUT_STOP, 0, 0);
  d13x_xspi_lut_write(2, LUT_READ, LUT_IO_1, 1, LUT_STOP, 0, 0);
  d13x_xspi_lut_update();
  putreg32(mr_addr, XSPI_ADDR_REG);
  d13x_xspi_trigger(0);
  *mr_val = (uint8_t)getreg32(XSPI_RDR);
}

static void d13x_psram_device_reset(void)
{
  d13x_xspi_lut_write(0, LUT_CMD, LUT_IO_1, 0xFF, LUT_STOP, 0, 0);
  d13x_xspi_lut_update();
  d13x_xspi_trigger(0);
}

static void d13x_psram_device_init(void)
{
  uint8_t mr4;

  /* 读取 MR4 检查配置 */

  d13x_psram_read_mr(0x04, &mr4);

  /* 配置 MR0: Burst Length = 32, Latency = 3 */

  d13x_psram_write_mr(0x00, 0x19);

  /* 配置 MR4: 使能 XIP */

  d13x_psram_write_mr(0x04, 0x80);
}

static void d13x_psram_xip_enable(void)
{
  /* 使能 XIP (CTL bit2) */

  uint32_t ctl = getreg32(XSPI_CTL);
  ctl |= CTL_XIP_EN;
  putreg32(ctl, XSPI_CTL);
}

uint32_t d13x_psram_verify(void)
{
  volatile uint32_t *psram = (volatile uint32_t *)PSRAM_BASE;
  uint32_t psram_size = d13x_psram_get_size();

  if (psram_size == 0)
    return 0;  /* 无法确定 PSRAM 大小 */

  /* 写入测试模式 */

  psram[0] = 0x12345678;
  psram[1] = 0x9ABCDEF0;

  /* 读取并验证 */

  if (psram[0] != 0x12345678)
    return 0;  /* PSRAM 读写失败 */

  if (psram[1] != 0x9ABCDEF0)
    return 0;  /* PSRAM 读写失败 */

  /* 清除测试数据 */

  psram[0] = 0;
  psram[1] = 0;

  return psram_size;
}

void d13x_psram_init(void)
{
  /* 首先验证 PSRAM 是否已初始化 */

  uint32_t psram_size = d13x_psram_verify();

  if (psram_size > 0)
    {
      print_str("PSRAM: Already initialized (");
      print_hex(psram_size);
      print_str(" bytes)\r\n");
      return;
    }

  print_str("PSRAM: Initializing...\r\n");

  /* 1. 使能 XSPI 时钟 (CMU_BASE + 0x45C = CLK_XSPI) */

  uint32_t reg = getreg32(CMU_BASE + 0x45C);
  reg |= (1 << 13) | (1 << 12) | (1 << 8);
  putreg32(reg, CMU_BASE + 0x45C);

  /* 2. 复位 XSPI 控制器 (写 0 到 CTL) */

  putreg32(0, XSPI_CTL);

  /* 3. 配置 XSPI 控制器 (来源: luban-lite hal_xspi_init) */

  putreg32(0, XSPI_CLK_REG);  /* 时钟分频 = 0 */

  xspi_wait_idle();
  putreg32((8 << 16) | (2 << 20), XSPI_TCR);  /* WR_HOLD=8, RD_HOLD=2 */

  /* XSPI 模式 = OPI */

  xspi_wait_idle();
  reg = getreg32(XSPI_CTL);
  reg |= (XSPI_MODE_OPI << CTL_XSPI_MODE_SHIFT);
  putreg32(reg, XSPI_CTL);

  /* 使能 wrap burst split + boundary */

  reg = getreg32(XSPI_CTL);
  reg |= CTL_AXI_BURST | CTL_BOUNDARY_EN | CTL_BOUNDARY_CTL;
  putreg32(reg, XSPI_CTL);

  /* IO 驱动配置 */

  putreg32(0x36363636, XSPI_CS0_IOCFG1);
  putreg32(0x36363636, XSPI_CS0_IOCFG2);
  putreg32(0x36363636, XSPI_CS0_IOCFG3);
  putreg32(0x37, XSPI_CS0_IOCFG4);

  /* DLL 配置 (ICP=150-200MHz, Phase=90度) */

  reg = getreg32(XSPI_CS0_DCTL);
  reg |= (2 << 12) | (3 << 8) | (1 << 4) | (1 << 5);
  putreg32(reg, XSPI_CS0_DCTL);
  reg |= (1 << 0) | (1 << 1) | (1 << 2);
  reg &= ~(1 << 3);
  putreg32(reg, XSPI_CS0_DCTL);

  /* 4. 使能 XSPI 模块 */

  xspi_wait_idle();
  reg = getreg32(XSPI_CTL);
  reg |= CTL_XSPI_EN;
  putreg32(reg, XSPI_CTL);

  /* 5. 复位 PSRAM 设备 */

  d13x_psram_device_reset();

  /* 6. 配置 PSRAM 模式寄存器 */

  d13x_psram_device_init();

  /* 7. 使能 XIP 模式 */

  d13x_psram_xip_enable();

  /* 8. 验证 */

  psram_size = d13x_psram_verify();

  if (psram_size > 0)
    {
      print_str("PSRAM: OK (");
      print_hex(psram_size);
      print_str(" bytes)\r\n");
    }
  else
    {
      print_str("PSRAM: Init failed!\r\n");
    }
}

